sys_script_include.script:
var updateProperties = Class.create();
updateProperties.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {

    updatePropertyValues: function() {

        try {
            //gs.info('Update Properties hello');

            var propName = this.getParameter('sysparm_propName');
            var propValue = this.getParameter('sysparm_value');

            // var propNameArr = [];
            // var propValueArr = [];

            // for (var j = 0; j < propName.split(",").length; j++) {
            //     propNameArr.push(propName.split(",")[j] + '');
            //     propValueArr.push(propValue.split(",")[j] + '');

            // }

            // gs.info('propNameArr ' + propNameArr.toString());
            // gs.info('propValueArr ' + propValueArr.toString());

            // for (i = 0; i < propNameArr.length; i++) {

            // gs.info('Within Update Properties for Loop Name outside Loop' + " " + i + " " + propNameArr[i]);
            // gs.info('Within Update Properties for Loop Value' + " " + i + " " + propValueArr[i]);
            var updateProperty = new GlideRecord("sys_properties");
            updateProperty.addEncodedQuery("name=" + propName.trim());
            updateProperty.query();
            if (updateProperty.next()) {

                updateProperty.value = propValue;
                updateProperty.update();
            }


            //}
        } catch (ex) {
            gs.info('Error From Update Properties ' + ex);
        }

    },
    type: 'updateProperties'
});
